"          ${(posSettings.printLoyaltyPoints && customerPhone && (posSettings.loyaltyPrintOption !== 'saved' || isSavedCustomer)) ? (() => {
            const fKey = customerPhone.startsWith('+') ? customerPhone : customerCountryCode + customerPhone;
            const rKey = customerPhone.startsWith('+') ? customerPhone.substring(customerCountryCode.length) : customerPhone;
            const cust = customerDb[fKey] || customerDb[customerPhone] || customerDb[rKey] || { points: 0 };
            const redeemed = pointsRedeemed;
            const earned = pointsEarnedOnBill;
            const isSettled = order.status === 'COMPLETED';
            const finalBalance = isSettled ? (cust.points || 0) : Math.max(0, (cust.points || 0) + earned - redeemed);

            return `
              <div class="dashed-line"></div>
              <div class="center" style="font-size: 10px; margin: 1mm 0; line-height: 1.3;">
                <div style="font-weight: bold;">★ LOYALTY REWARDS SUMMARY ★</div>
                <div style="display: flex; justify-content: space-between; margin-top: 1mm;">
                  <span>Points Earned this Visit:</span>
                  <span><strong>+${earned} Pts</strong></span>
                </div>
                ${redeemed > 0 ? `
                <div style="display: flex; justify-content: space-between;">
                  <span>Points Redeemed:</span>
                  <span><strong>-${redeemed} Pts</strong></span>
                </div>
                ` : ''}
                <div style="display: flex; justify-content: space-between; font-weight: bold; border-top: 1px dashed #000; margin-top: 0.5mm; padding-top: 0.5mm;">
                  <span>Total Accumulated Balance:</span>
                  <span>${finalBalance} Pts</span>
                </div>
              </div>
            `;
          })() : ''}"
